{"code": "import os
from PIL import Image

PATH = 'data_small/cats_and_dogs'
train_dir = os.path.join(PATH, 'train')
cats_dir = os.path.join(train_dir, 'cats')
dogs_dir = os.path.join(train_dir, 'dogs')

corrupted_files = []

for directory in [cats_dir, dogs_dir]:
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        try:
            with Image.open(filepath) as img:
                img.verify()  # Verify it's a valid image
                # Verify closes the file, so need to reopen to check
                img = Image.open(filepath)
                img.load()  # Actually try to load it
        except Exception as e:
            corrupted_files.append((filepath, str(e)))

print(f"Total corrupted files found: {len(corrupted_files)}")
if corrupted_files:
    print("\nFirst few corrupted files:")
    for filepath, error in corrupted_files[:10]:
        print(f"  {os.path.basename(filepath)}: {error}")
else:
    print("No corrupted files found")"}

