PATH = 'data_small/cats_and_dogs'

# Check all images
total_valid = 0
total_corrupted = 0

for root, dirs, files in os.walk(PATH):
    for file in files:
        if file.endswith('.jpg'):
            filepath = os.path.join(root, file)
            try:
                img = Image.open(filepath)
                img.verify()
